 /// <summary>Simple in-memory notebook for storing research notes.</summary>
 sealed class Notebook
 {
     private readonly List<(string Title, string Content)> _notes = [];

     public void Add(string title, string content) => _notes.Add((title, content));

     public string GetAll()
     {
         if (_notes.Count == 0) return "No notes saved yet.";

         var sb = new StringBuilder();
         for (var i = 0; i < _notes.Count; i++)
         {
             sb.AppendLine($"## Note {i + 1}: {_notes[i].Title}");
             sb.AppendLine(_notes[i].Content);
             sb.AppendLine();
         }
         return sb.ToString();
     }
 }

 /// <summary>Web search using DuckDuckGo HTML endpoint.</summary>
 static class WebSearch
 {
     private static readonly HttpClient Http = new()
     {
         DefaultRequestHeaders =
         {
             { "User-Agent", "ResearchAgent/1.0" },
             { "Accept", "text/html" },
         },
         Timeout = TimeSpan.FromSeconds(15),
     };

     public static async Task<string> SearchAsync(string query)
     {
         Console.WriteLine($"  🔍 Searching: \"{query}\"");

         try
         {
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://html.duckduckgo.com/html/?q={encoded}";
             var html = await Http.GetStringAsync(url);

             var snippets = ParseSnippets(html);
             if (snippets.Count == 0)
                 return "No results found.";

             var sb = new StringBuilder();
             for (var i = 0; i < Math.Min(snippets.Count, 5); i++)
             {
                 sb.AppendLine($"{i + 1}. {snippets[i]}");
             }
             return sb.ToString();
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}";
         }
     }

     private static List<string> ParseSnippets(string html)
     {
         var results = new List<string>();
         var snippetMarker = "class=\"result__snippet\"";

         var index = 0;
         while ((index = html.IndexOf(snippetMarker, index, StringComparison.Ordinal)) >= 0)
         {
             var start = html.IndexOf('>', index) + 1;
             if (start <= 0) break;

             var end = html.IndexOf("</", start, StringComparison.Ordinal);
             if (end < 0) break;

             var snippet = html[start..end]
                 .Replace("<b>", "").Replace("</b>", "")
                 .Replace("&amp;", "&").Replace("&quot;", "\"")
                 .Replace("&#x27;", "'").Replace("&lt;", "<")
                 .Replace("&gt;", ">")
                 .Trim();

             if (snippet.Length > 0)
                 results.Add(snippet);

             index = end;
         }
         return results;
     }
 }
